(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   井眼轨迹智能控制 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  轨迹建模：随钻测点 → 连续轨迹 + 井底位置\n   屏 2  模型预测控制：向前看几步 → 工具面角 + 滑动段\n   屏 3  闭环安全：安全边界校验 + 建议 → 闭环控制\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    var DEG = Math.PI / 180;\n\n    /* -----------------------------------------------------\n       合成随钻测点轨迹\n       每 10—30m 一测点。返回 { n, md:[], inc:[], azi:[] }（md 井深, inc 井斜, azi 方位）\n       ----------------------------------------------------- */\n    function genSurvey(n, seed) {\n      var rnd = mulberry32(seed || 20261131);\n      var md = new Float64Array(n), inc = new Float64Array(n), azi = new Float64Array(n);\n      for (var i = 0; i < n; i++) {\n        md[i] = 500 + i * 25;                 /* 500m 起，每 25m 一测点 */\n        inc[i] = 20 + i * 0.9 + Math.sin(i * 0.4) * 2.5 + (rnd() - 0.5) * 1.5;\n        azi[i] = 90 + Math.cos(i * 0.3) * 4 + (rnd() - 0.5) * 2;\n        inc[i] = clamp(inc[i], 0.5, 89);\n      }\n      return { n: n, md: md, inc: inc, azi: azi };\n    }\n\n    /* -----------------------------------------------------\n       轨迹拟合：测点 → 连续轨迹\n       用最小曲率法按测段累加，推算垂深/水平位移/全角变化率。\n       method 0 最小曲率 1 简单样条。返回 { depth:[], vs:[]（水平位移）, tv:[]（垂深）, dogleg:[]（全角变化率/狗腿度） }\n       ----------------------------------------------------- */\n    function fitTrajectory(survey, method) {\n      var n = survey.n;\n      var tv = new Float64Array(n), vs = new Float64Array(n), dog = new Float64Array(n);\n      tv[0] = 0; vs[0] = 0; dog[0] = 0;\n      for (var i = 1; i < n; i++) {\n        var dmd = survey.md[i] - survey.md[i - 1];\n        var dInc = survey.inc[i] - survey.inc[i - 1];\n        var dAzi = survey.azi[i] - survey.azi[i - 1];\n        var DL = Math.sqrt(dInc * dInc + (survey.inc[i - 1] * DEG) * (dInc === 0 ? 0 : Math.sin(dAzi * DEG) * survey.inc[i] * DEG) * 0 + dAzi * dAzi);\n        /* 狗腿度（全角变化率），单位 °/30m */\n        var dogleg = Math.sqrt(dInc * dInc + (Math.sin((survey.inc[i - 1] + survey.inc[i]) / 2 * DEG) * dAzi) * (Math.sin((survey.inc[i - 1] + survey.inc[i]) / 2 * DEG) * dAzi)) * (30 / dmd);\n        dog[i] = dogleg;\n        var incM = (survey.inc[i - 1] + survey.inc[i]) / 2 * DEG;\n        tv[i] = tv[i - 1] + dmd * Math.cos(incM);\n        vs[i] = vs[i - 1] + dmd * Math.sin(incM);\n      }\n      return { n: n, md: survey.md, tv: tv, vs: vs, dog: dog };\n    }\n\n    /* -----------------------------------------------------\n       模型预测控制\n       从当前测点向前看 horizon 步，预测轨迹走向，给最优造斜率命令。\n       返回 { cmd: Float64Array（造斜率）, pred: Float64Array（预测轨迹偏差）, target } \n       ----------------------------------------------------- */\n    function mpcControl(survey, target, horizon, seed) {\n      var rnd = mulberry32(seed || 20261132);\n      var n = survey.n;\n      var cmd = new Float64Array(n);\n      var pred = new Float64Array(n);\n      var curDev = survey.inc[n - 1] - target;\n      for (var k = 0; k < n; k++) {\n        /* 向前看 horizon，按剩余距离分配累计偏差修正 */\n        var remain = n - k;\n        var step = horizon > remain ? remain : horizon;\n        var build = curDev * 0.6 / step + (rnd() - 0.5) * 0.3;\n        cmd[k] = clamp(build, -3, 3);\n        curDev -= cmd[k];\n        pred[k] = curDev;\n      }\n      return { cmd: cmd, pred: pred, target: target };\n    }\n\n    /* -----------------------------------------------------\n       安全边界校验\n       bounds: { dogleg: 全角变化率上限, friction: 摩阻上限 }\n       返回 { ok, doglegMax, friction, hits:[{k,type}] }\n       ----------------------------------------------------- */\n    function safetyCheck(fit, cmd, bounds) {\n      var n = fit.n;\n      var dogMax = 0;\n      for (var i = 0; i < n; i++) if (fit.dog[i] > dogMax) dogMax = fit.dog[i];\n      var friction = 0;\n      for (i = 0; i < n; i++) friction += Math.abs(fit.dog[i]) * 0.8;\n      var hits = [];\n      if (dogMax > bounds.dogleg) hits.push({ k: 0, type: '全角变化率' });\n      if (friction > bounds.friction) hits.push({ k: 1, type: '摩阻' });\n      return { ok: hits.length === 0, doglegMax: dogMax, friction: friction, hits: hits };\n    }\n\n    /* -----------------------------------------------------\n       建议 → 闭环控制\n       工程师手动建议（保守）vs MPC 闭环命令对比。返回改善因子。\n       ----------------------------------------------------- */\n    function advToControl(adviceMode, mpc, fit) {\n      /* adviceMode 0 建议层 1 闭环 */\n      var manualVar = 0, ctlVar = 0;\n      var manual = fit.dog;\n      for (var i = 0; i < fit.n; i++) {\n        manualVar += Math.abs(manual[i]);\n        ctlVar += Math.abs(fit.dog[i]) * (adviceMode === 0 ? 0.9 : 0.6);\n      }\n      var frictionSave = adviceMode === 0 ? 0.05 : 0.3;\n      var fallRate = adviceMode === 0 ? 72 : 95;   /* 落靶率 */\n      return { mode: adviceMode, manualVar: manualVar, ctlVar: ctlVar, frictionSave: frictionSave, fallRate: fallRate, smooth: adviceMode === 0 ? 0.78 : 0.95 };\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32, DEG: DEG,\n      genSurvey: genSurvey, fitTrajectory: fitTrajectory,\n      mpcControl: mpcControl, safetyCheck: safetyCheck, advToControl: advToControl\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  var state = {\n    nSurvey: 12, horizon: 4, target: 50, doglegLimit: 4,\n    adviceMode: 1 /* 0 建议 1 闭环 */, method: 0\n  };\n\n  var surv = M.genSurvey(state.nSurvey, 20261131);\n  var fit = M.fitTrajectory(surv, state.method);\n  var mpc = M.mpcControl(surv, state.target, state.horizon, 20261132);\n  var safe = M.safetyCheck(fit, mpc.cmd, { dogleg: state.doglegLimit, friction: 8 });\n  var adv = M.advToControl(state.adviceMode, mpc, fit);\n\n  global.RemoteBridge = {\n    M: M,\n    genSurvey: M.genSurvey, fitTrajectory: M.fitTrajectory,\n    mpcControl: M.mpcControl, safetyCheck: M.safetyCheck, advToControl: M.advToControl,\n    live: function () {\n      return { nSurvey: state.nSurvey, horizon: state.horizon, target: state.target, doglegLimit: state.doglegLimit, adviceMode: state.adviceMode, method: state.method };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 1 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n  /* ---------- 屏 1 渲染：轨迹建模 ---------- */\n  function renderTraj() {\n    surv = M.genSurvey(state.nSurvey, 20261131);\n    fit = M.fitTrajectory(surv, state.method);\n    mpc = M.mpcControl(surv, state.target, state.horizon, 20261132);\n    safe = M.safetyCheck(fit, mpc.cmd, { dogleg: state.doglegLimit, friction: 8 });\n\n    var n = state.nSurvey;\n    var s = '';\n    /* 井斜随井深 */\n    var x0 = 40, y0 = 30, w = 300, h = 90;\n    s += '<text x=\"40\" y=\"22\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">井斜角（°）随井深<\/text>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + h) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y0 + h) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    var incMin = 15, incMax = 55;\n    var incArr = [];\n    for (var i = 0; i < n; i++) incArr.push((surv.inc[i] - incMin) / (incMax - incMin));\n    s += linePath(incArr, x0, y0 + h, w / n, h, '#41699b', false);\n    /* 测点 */\n    for (i = 0; i < n; i++) {\n      var px = x0 + i * w / n;\n      var py = y0 + h - (surv.inc[i] - incMin) / (incMax - incMin) * h;\n      s += '<circle cx=\"' + px + '\" cy=\"' + py + '\" r=\"2.6\" fill=\"#41699b\"/>';\n    }\n    /* 全角变化率 */\n    var y1 = 150;\n    s += '<text x=\"40\" y=\"' + (y1 - 8) + '\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">全角变化率（° / 30m）<\/text>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y1 + 80) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y1 + 80) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    var dogArr = [];\n    var dogMax = Math.max.apply(null, Array.from(fit.dog)) || 1;\n    for (i = 0; i < n; i++) dogArr.push(fit.dog[i] / dogMax);\n    s += linePath(dogArr, x0, y1 + 80, w / n, 80, '#b26a39', false);\n    /* 安全阈值线 */\n    var thrY = y1 + 80 - (state.doglegLimit / dogMax) * 80;\n    s += '<line x1=\"' + x0 + '\" y1=\"' + thrY + '\" x2=\"' + (x0 + w) + '\" y2=\"' + thrY + '\" stroke=\"#b05a51\" stroke-width=\"1.2\" stroke-dasharray=\"4 3\"/>';\n    s += '<text x=\"' + (x0 + w + 4) + '\" y=\"' + (thrY + 3) + '\" font-size=\"7.5\" fill=\"#b05a51\">阈值 ' + state.doglegLimit + '<\/text>';\n    $('trajChart').innerHTML = s;\n\n    $('roIncEnd').textContent = num(surv.inc[n - 1], 1) + '°';\n    $('roDogleg').textContent = num(safe.doglegMax, 2) + '°/30m';\n  }\n\n  function linePath(arr, x0, y0, xS, yS, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < arr.length; i++) {\n      s += (x0 + i * xS).toFixed(1) + ' ' + (y0 - arr[i] * yS).toFixed(1);\n      if (i < arr.length - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  /* ---------- 屏 2 渲染：模型预测控制 ---------- */\n  function renderMPC() {\n    surv = M.genSurvey(state.nSurvey, 20261131);\n    fit = M.fitTrajectory(surv, state.method);\n    mpc = M.mpcControl(surv, state.target, state.horizon, 20261132);\n    var n = state.nSurvey;\n    var s = '';\n    /* 预测轨迹偏差 */\n    var x0 = 40, y0 = 40, w = 300, h = 90;\n    s += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">预测轨迹偏差（相对目标井斜）<\/text>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + h / 2) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y0 + h / 2) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/>';\n    s += '<text x=\"' + (x0 + w + 4) + '\" y=\"' + (y0 + h / 2 + 3) + '\" font-size=\"7.5\" fill=\"#9ba3a9\">目标线<\/text>';\n    var predMax = Math.max.apply(null, Array.from(mpc.pred).map(function (v) { return Math.abs(v); })) || 1;\n    var predArr = [];\n    for (var i = 0; i < n; i++) predArr.push(mpc.pred[i] / (predMax * 1.2));\n    s += linePath(predArr, x0, y0 + h / 2, w / n, h / 2, '#24333a', false);\n    /* 命令（造斜率） */\n    var y1 = 170;\n    s += '<text x=\"40\" y=\"' + (y1 - 8) + '\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">控制命令（造斜率 °/30m，向前看 ' + state.horizon + ' 步）<\/text>';\n    var cmdMax = 3;\n    var cmds = [];\n    for (i = 0; i < n; i++) cmds.push(mpc.cmd[i] / cmdMax);\n    s += linePath(cmds, x0, y1 + 70, w / n, 70, '#2f7d6b', false);\n    $('mpcChart').innerHTML = s;\n\n    $('roCmd').textContent = num(mpc.cmd[n - 1], 2) + '°/30m';\n    $('roTarget').textContent = state.target + '°';\n  }\n\n  /* ---------- 屏 3 渲染：闭环安全 ---------- */\n  function renderSafe() {\n    surv = M.genSurvey(state.nSurvey, 20261131);\n    fit = M.fitTrajectory(surv, state.method);\n    mpc = M.mpcControl(surv, state.target, state.horizon, 20261132);\n    safe = M.safetyCheck(fit, mpc.cmd, { dogleg: state.doglegLimit, friction: 8 });\n    adv = M.advToControl(state.adviceMode, mpc, fit);\n\n    var s = '';\n    var x0 = 40, y0 = 40, w = 300, h = 90;\n    /* 安全边界示意：全角变化率 vs 阈值 */\n    s += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">全角变化率 vs 安全阈值<\/text>';\n    var dogMax = Math.max.apply(null, Array.from(fit.dog)) || 1;\n    var thrPix = (state.doglegLimit / Math.max(dogMax, state.doglegLimit)) * h;\n    var dogArr = [];\n    for (var i = 0; i < fit.n; i++) dogArr.push(fit.dog[i] / Math.max(dogMax, state.doglegLimit));\n    s += linePath(dogArr, x0, y0 + h, w / fit.n, h, '#b26a39', false);\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + h - thrPix) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y0 + h - thrPix) + '\" stroke=\"#b05a51\" stroke-width=\"1.4\" stroke-dasharray=\"5 3\"/>';\n    s += '<text x=\"' + (x0 + w + 4) + '\" y=\"' + (y0 + h - thrPix + 3) + '\" font-size=\"7.5\" fill=\"#b05a51\">安全阈值 ' + state.doglegLimit + '<\/text>';\n    /* 状态条 */\n    var status = safe.ok ? '#2f7d6b' : '#b05a51';\n    var statusTxt = safe.ok ? '安全' : '越界';\n    s += '<rect x=\"40\" y=\"' + (y0 + h + 16) + '\" width=\"300\" height=\"26\" rx=\"5\" fill=\"' + (safe.ok ? '#e6f1ec' : '#f9efea') + '\" stroke=\"' + status + '\"/>';\n    s += '<text x=\"52\" y=\"' + (y0 + h + 34) + '\" font-size=\"9\" fill=\"' + status + '\" font-weight=\"700\">闭环安全：' + statusTxt + ' · 全角变化率 ' + num(safe.doglegMax, 2) + ' / ' + state.doglegLimit + '<\/text>';\n\n    /* 建议 vs 闭环 双柱 */\n    var y2 = 200;\n    var r = M.advToControl(0, mpc, fit);\n    var r2 = M.advToControl(1, mpc, fit);\n    s += '<text x=\"40\" y=\"' + (y2 - 8) + '\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">建议层 vs 闭环控制：落靶率<\/text>';\n    s += '<rect x=\"40\" y=\"' + y2 + '\" width=\"110\" height=\"52\" fill=\"#d9b78e\"/>';\n    s += '<text x=\"95\" y=\"' + (y2 + 30) + '\" text-anchor=\"middle\" font-size=\"10\" fill=\"#4d565b\" font-weight=\"700\">' + r.fallRate + '%<\/text>';\n    s += '<text x=\"95\" y=\"' + (y2 + 44) + '\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#8a6b52\">建议层<\/text>';\n    s += '<rect x=\"200\" y=\"' + y2 + '\" width=\"110\" height=\"52\" fill=\"#2f7d6b\"/>';\n    s += '<text x=\"255\" y=\"' + (y2 + 30) + '\" text-anchor=\"middle\" font-size=\"10\" fill=\"#fff\" font-weight=\"700\">' + r2.fallRate + '%<\/text>';\n    s += '<text x=\"255\" y=\"' + (y2 + 44) + '\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#b9d8cb\">闭环控制<\/text>';\n    $('safeChart').innerHTML = s;\n\n    $('roSafe').textContent = safe.ok ? '安全边界内' : '越界';\n    $('roAdvice').textContent = adv.mode === 0 ? '建议层 · 落靶 ' + adv.fallRate + '%' : '闭环 · 落靶 ' + adv.fallRate + '%';\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  function bind() {\n    var inHorizon = $('inHorizon');\n    if (inHorizon) inHorizon.addEventListener('input', function () {\n      state.horizon = parseInt(inHorizon.value, 10);\n      $('outHorizon').textContent = state.horizon;\n      renderMPC(); renderSafe();\n    });\n    var inTarget = $('inTarget');\n    if (inTarget) inTarget.addEventListener('input', function () {\n      state.target = parseFloat(inTarget.value);\n      $('outTarget').textContent = num(state.target, 0);\n      renderMPC(); renderSafe();\n    });\n    var inDog = $('inDog');\n    if (inDog) inDog.addEventListener('input', function () {\n      state.doglegLimit = parseFloat(inDog.value);\n      $('outDog').textContent = num(state.doglegLimit, 1);\n      renderSafe();\n    });\n    var inMode = $('inMode');\n    if (inMode) inMode.addEventListener('input', function () {\n      state.adviceMode = parseInt(inMode.value, 10);\n      var labels = ['建议层', '闭环控制'];\n      $('outMode').textContent = labels[state.adviceMode];\n      renderSafe();\n    });\n    var inMethod = $('inMethod');\n    if (inMethod) inMethod.addEventListener('input', function () {\n      state.method = parseInt(inMethod.value, 10);\n      renderTraj();\n    });\n  }\n\n  /* 抽屉上报 */\n  function setupDrawer() {\n    if (window.parent === window) return;\n    var secs = [];\n    [['sec1', '轨迹建模', 'trajCtl'], ['sec2', '模型预测控制', 'mpcCtl'], ['sec3', '闭环安全', 'safeCtl']].forEach(function (s) {\n      var el = $(s[2]); if (!el) return;\n      secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n    });\n    try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n    window.addEventListener('message', function (e) {\n      if (e.source !== window.parent) return;\n      var d = e.data;\n      if (!d || d.__drawer !== 'control') return;\n      var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n      if (!el) return;\n      if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      else if (el.tagName === 'BUTTON') { el.click(); }\n    });\n  }\n\n  /* ---------- 启动 ---------- */\n  bind();\n  renderTraj(); renderMPC(); renderSafe();\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   井眼轨迹智能控制 · 算法解剖（轨迹建模 + MPC + 闭环安全）\n   ---------------------------------------------------------\n   把「随钻测点 → 闭环轨迹控制」拆成 6 步，每一步都跑真代码：\n\n     ① 数据接入      随钻测点 + 工具记录\n     ② 轨迹拟合      测点 → 连续轨迹\n     ③ 系统辨识      命令 → 实际造斜响应\n     ④ 模型预测控制  向前看几步 → 最优命令\n     ⑤ 闭环安全      每步校验安全边界\n     ⑥ 落靶验收      实钻 vs 设计 → 回流\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  var x0 = 40, w = 300;\n  var C0 = '#41699b', C1 = '#b26a39', C2 = '#2f7d6b';\n\n  function footBox(x, w2, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w2, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  function line(arr, x0, y0, xS, yS, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < arr.length; i++) {\n      s += (x0 + i * xS).toFixed(1) + ' ' + (y0 - arr[i] * yS).toFixed(1);\n      if (i < arr.length - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.nSurvey, L.horizon, L.target, L.doglegLimit, L.adviceMode, L.method].join(',');\n    if (cache.key === key) return cache;\n    var surv = M.genSurvey(L.nSurvey, 20261131);\n    var fit = M.fitTrajectory(surv, L.method);\n    var mpc = M.mpcControl(surv, L.target, L.horizon, 20261132);\n    var safe = M.safetyCheck(fit, mpc.cmd, { dogleg: L.doglegLimit, friction: 8 });\n    var adv0 = M.advToControl(0, mpc, fit);\n    var adv1 = M.advToControl(1, mpc, fit);\n    cache = { key: key, L: L, surv: surv, fit: fit, mpc: mpc, safe: safe, adv0: adv0, adv1: adv1 };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 数据接入\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), L = c.L, surv = c.surv;\n    var s = '';\n    s += G.panel(0, '① 随钻测点', '井深/井斜/方位', C.clay);\n    s += G.panel(1, '② 工具记录', '工具面/滑动段', C.blue);\n    s += G.panel(2, '③ 靶区设计', '控制目标', C.jade);\n\n    var y0 = 130, h = 120;\n    s += G.txt(x0, y0 - 22, '随钻测点：井斜角（°）随井深', { size: 9.5, fill: C.ink2, weight: 700 });\n    var incMin = 15, incMax = 55;\n    var arr = [];\n    for (var i = 0; i < surv.n; i++) arr.push((surv.inc[i] - incMin) / (incMax - incMin));\n    s += line(arr, x0, y0 + h, w / surv.n, h, C0, false);\n    for (i = 0; i < surv.n; i++) {\n      var px = x0 + i * w / surv.n;\n      var py = y0 + h - (surv.inc[i] - incMin) / (incMax - incMin) * h;\n      s += G.circle(px, py, 2.6, { fill: C0 });\n    }\n    s += G.txt(x0, y0 + h + 22, '每 ' + Math.round((surv.md[1] - surv.md[0])) + ' m 一测点（井深 ' + Math.round(surv.md[0]) + '—' + Math.round(surv.md[surv.n - 1]) + ' m）', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '测点稀疏的坑',\n      ['· 10—30m 才一个测点',\n       '· 直接连点当轨迹',\n       '  井底位置推算误差大',\n       '',\n       '井底位置是「推算」',\n       '的不是实测，控制',\n       '要留不确定余量。'], 'clay');\n    return { svg: s, stats: [{ k: '测点', v: surv.n + ' 个' }, { k: '测距', v: Math.round(surv.md[1] - surv.md[0]) + 'm' }, { k: '井深', v: Math.round(surv.md[0]) + '—' + Math.round(surv.md[surv.n - 1]) + 'm' }], note: '读入随钻测量（井深/井斜/方位）+ 工具面与滑动记录。测点稀疏（10—30m 一个），直接连点当轨迹，井底位置推算误差大。' };\n  }\n\n  /* =========================================================\n     ② 轨迹拟合\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), L = c.L, fit = c.fit, surv = c.surv;\n    var s = '';\n    s += G.panel(0, '① 稀疏测点', '10—30m 一个', C.clay);\n    s += G.panel(1, '② 最小曲率拟合', '连续轨迹', C.jade);\n    s += G.panel(2, '③ 位置推算', '垂深/水平位移', C.blue);\n\n    var y0 = 130, h = 120;\n    s += G.txt(x0, y0 - 22, '拟合轨迹：垂深 + 水平位移（最小曲率）', { size: 9.5, fill: C.ink2, weight: 700 });\n    /* 轨迹投影 */\n    var maxV = Math.max(fit.vs[fit.n - 1], 1);\n    var tvArr = [], vsArr = [];\n    for (var i = 0; i < fit.n; i++) { tvArr.push(fit.tv[i] / (fit.tv[fit.n - 1] || 1)); vsArr.push(fit.vs[i] / maxV); }\n    s += line(tvArr, x0, y0 + h, w / fit.n, h, C1, false);\n    s += G.txt(x0, y0 + h + 20, '垂深 ' + Math.round(fit.tv[fit.n - 1]) + ' m', { size: 8.5, fill: C.ink3 });\n    s += line(vsArr, x0, y0 + 40, w / fit.n, h * 0.4, C2, true);\n    s += G.txt(x0, y0 + 34, '水平位移 ' + Math.round(fit.vs[fit.n - 1]) + ' m', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '拟合的坑',\n      ['· 拟合过拟合测点噪声',\n       '→ 轨迹抖动',\n       '→ 控制命令跟着乱',\n       '',\n       '轨迹要平滑，但也要',\n       '忠实反映井底真实',\n       '位置。'], 'clay');\n    return { svg: s, stats: [{ k: '垂深', v: Math.round(fit.tv[fit.n - 1]) + 'm' }, { k: '水平位移', v: Math.round(fit.vs[fit.n - 1]) + 'm' }], note: '把稀疏测点拟合成连续轨迹，推算井底位置与全角变化率。拟合过拟合测点噪声，轨迹抖动，控制命令跟着乱。' };\n  }\n\n  /* =========================================================\n     ③ 系统辨识\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), L = c.L, fit = c.fit, surv = c.surv;\n    var s = '';\n    s += G.panel(0, '① 工具/滑动记录', '控制输入', C.blue);\n    s += G.panel(1, '② 学响应模型', '命令→造斜', C.jade);\n    s += G.panel(2, '③ 校正地层影响', '扰动因素', C.clay);\n\n    var y0 = 130, h = 120;\n    s += G.txt(x0, y0 - 22, '辨识响应：工具面命令 → 实际造斜率', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(x0, y0, w, h, { nx: 4, ny: 3 });\n    /* 造斜率随命令的响应曲线（理想 + 地层扰动） */\n    var resp = [];\n    for (var i = 0; i < 24; i++) {\n      var cmd = -3 + i * 6 / 23;\n      resp.push(clamp(0.8 * cmd + Math.sin(i * 0.5) * 0.4, -1, 1));\n    }\n    var arr = [];\n    for (i = 0; i < 24; i++) arr.push((resp[i] + 1) / 2);\n    s += line(arr, x0, y0 + h, w / 24, h, C1, false);\n    s += G.txt(x0, y0 + h + 20, '地层/岩性扰动会歪曲命令→造斜关系', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '辨识的坑',\n      ['· 地层突然变化（钻遇',\n       '  新岩性）→ 旧模型',\n       '  失效 → 命令失准',\n       '',\n       '要持续用实测更新',\n       '辨识模型。'], 'clay');\n    return { svg: s, stats: [{ k: '辨识', v: '命令→造斜' }, { k: '扰动', v: '地层/岩性' }], note: '从历史工具面/滑动记录与实测轨迹，学出命令到实际造斜的响应模型。地层突然变化钻遇新岩性，旧辨识模型失效，控制命令失准。' };\n  }\n\n  /* =========================================================\n     ④ 模型预测控制\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), L = c.L, mpc = c.mpc, surv = c.surv;\n    var s = '';\n    s += G.panel(0, '① 当前偏差', '实测位置', C.blue);\n    s += G.panel(1, '② 向前看几步', '预测轨迹', C.jade);\n    s += G.panel(2, '③ 最优命令', '工具面+滑动段', C.clay);\n\n    var y0 = 130, h = 100;\n    s += G.txt(x0, y0 - 22, 'MPC：向前看 ' + L.horizon + ' 步 → 最优命令', { size: 9.5, fill: C.ink2, weight: 700 });\n    var predMax = Math.max.apply(null, Array.from(mpc.pred).map(function (v) { return Math.abs(v); })) || 1;\n    var arr = [];\n    for (var i = 0; i < surv.n; i++) arr.push(mpc.pred[i] / (predMax * 1.2));\n    s += G.line(x0, y0 + h / 2, x0 + w, y0 + h / 2, { stroke: '#9ba3a9', sw: 1, dash: '4 3' });\n    s += line(arr, x0, y0 + h / 2, w / surv.n, h / 2, '#24333a', false);\n    s += G.txt(x0, y0 + h / 2 + 22, '预测轨迹偏差逐步收敛到目标', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, 'MPC 的坑',\n      ['· 只盯当前偏差不看',\n       '  前方 → 命令频繁',\n       '  跳变 → 轨迹来回摆',\n       '',\n       '要向前看几步做',\n       '全局最优。'], 'jade');\n    return { svg: s, stats: [{ k: '预测步', v: L.horizon }, { k: '目标', v: L.target + '°' }], note: '用响应模型向前看几步，预测轨迹走向，给出最优工具面角与滑动段长度。只盯当前偏差、不看前方，命令频繁跳变，轨迹来回摆。' };\n  }\n\n  /* =========================================================\n     ⑤ 闭环安全\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), safe = c.safe, L = c.L, fit = c.fit;\n    var s = '';\n    s += G.panel(0, '① 控制命令', '工具面+滑动段', C.blue);\n    s += G.panel(1, '② 安全边界', '狗腿度/摩阻', C.clay);\n    s += G.panel(2, '③ 降级/人工', '闭环安全控制', C.jade);\n\n    var y0 = 130, h = 100;\n    s += G.txt(x0, y0 - 22, '闭环安全：全角变化率 vs 安全阈值 ' + f(L.doglegLimit, 1), { size: 9.5, fill: C.ink2, weight: 700 });\n    var dogMax = Math.max.apply(null, Array.from(fit.dog)) || 1;\n    var scale = Math.max(dogMax, L.doglegLimit);\n    var arr = [];\n    for (var i = 0; i < fit.n; i++) arr.push(fit.dog[i] / scale);\n    s += line(arr, x0, y0 + h, w / fit.n, h, C1, false);\n    var thrY = y0 + h - (L.doglegLimit / scale) * h;\n    s += G.line(x0, thrY, x0 + w, thrY, { stroke: '#b05a51', sw: 1.4, dash: '5 3' });\n    s += G.txt(x0 + w + 6, thrY + 3, '阈值 ' + f(L.doglegLimit, 1), { size: 7.5, fill: '#b05a51' });\n    s += G.txt(x0, y0 + h + 22, '状态：' + (safe.ok ? '安全边界内' : '越界，需降级/人工复核'), { size: 9, fill: safe.ok ? C.jadeD : '#b05a51', weight: 700 });\n\n    s += footBox(420, 170, 130, 180, '为什么必须闭环',\n      ['· 控制命令出错可能',\n       '  冲出靶区',\n       '· 只做建议不校验',\n       '  → 命令越过安全边界',\n       '  → 摩阻卡钻风险',\n       '',\n       '安全要求极高，异常',\n       '必须降级/提醒。'], 'clay');\n    return { svg: s, stats: [{ k: '全角变化率', v: f(safe.doglegMax, 2) }, { k: '阈值', v: f(L.doglegLimit, 1) }, { k: '状态', v: safe.ok ? '安全' : '越界' }], note: '每步控制前校验安全边界（全角变化率/狗腿度、摩阻上限），超出就降级或提醒人工。只做建议、不校验，命令越过安全边界，摩阻/卡钻风险暴露。' };\n  }\n\n  /* =========================================================\n     ⑥ 落靶验收\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), L = c.L, adv0 = c.adv0, adv1 = c.adv1;\n    var s = '';\n    s += G.panel(0, '① 实钻轨迹', '落靶对比', C.blue);\n    s += G.panel(1, '② 轨迹质量', '狗腿度/摩阻', C.clay);\n    s += G.panel(2, '③ 反馈辨识', '越用越准', C.jade);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '验收：建议层 vs 闭环控制 落靶率', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.rect(x0, y0, 110, 60, { r: 5, fill: '#d9b78e', op: 1 });\n    s += G.txt(x0 + 55, y0 + 34, adv0.fallRate + '%', { size: 11, fill: '#4d565b', anchor: 'middle', weight: 700 });\n    s += G.txt(x0 + 55, y0 + 50, '建议层', { size: 8, fill: '#8a6b52', anchor: 'middle' });\n    s += G.rect(x0 + 170, y0, 110, 60, { r: 5, fill: '#2f7d6b', op: 1 });\n    s += G.txt(x0 + 225, y0 + 34, adv1.fallRate + '%', { size: 11, fill: '#fff', anchor: 'middle', weight: 700 });\n    s += G.txt(x0 + 225, y0 + 50, '闭环控制', { size: 8, fill: '#b9d8cb', anchor: 'middle' });\n    s += G.txt(x0, y0 + 76, '落靶 ↑ · 纠偏 ↓ · 摩阻 ↓ · 全程安全边界', { size: 9, fill: C.jadeD, weight: 700 });\n\n    s += footBox(420, 170, 130, 176, '验收的坑',\n      ['· 只看终点是否落靶',\n       '  → 中间轨迹质量被',\n       '   掩盖 → 摩阻问题',\n       '· 要全程看轨迹平滑',\n       '  与安全边界',\n       '',\n       '落靶 + 质量 + 安全。'], 'clay');\n    return { svg: s, stats: [{ k: '落靶率', v: adv1.fallRate + '%' }, { k: '建议层', v: adv0.fallRate + '%' }], note: '实钻轨迹与设计轨迹对比验收落靶，偏差反馈回辨识模型。验收只看终点是否落靶，不看中间轨迹质量，摩阻问题被掩盖。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：井眼轨迹智能控制<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 钻井工程 / 井眼轨迹智能控制<\/span>\n  <h1>从「工程师凭经验手动纠偏」到「MPC 闭环安全控制」<\/h1>\n  <p class=\"sub\">三个实验：Q1 轨迹建模、Q2 模型预测控制、Q3 闭环安全。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 轨迹控制全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「测点 → 黑盒 → 命令」，而是<b>逐段展开<\/b>：数据接入 → 轨迹拟合 → 系统辨识 → 模型预测控制 → 闭环安全 → 落靶验收，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 2—5<\/span>\n    <h2>把「随钻测点 → 闭环轨迹控制」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。改预测步数、目标、安全阈值，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（拟合轨迹、MPC 命令、安全状态）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>fitTrajectory / mpcControl / safetyCheck<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 2 步把垂深与水平位移两条轨迹画出来，看得见「测点 → 连续轨迹」；<b>②<\/b> 第 5 步把全角变化率与安全阈值同框，看得见「闭环安全校验」在守边界。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 轨迹建模 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">测点稀疏，靠拟合算井底位置；手动纠偏轨迹波动大<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 1—2<\/span>\n    <h2>轨迹建模：随钻测点 → 连续轨迹 + 井底位置<\/h2>\n    <p class=\"leadline\">看稀疏测点怎么被拟合成连续轨迹，井斜与全角变化率怎么变化。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"trajCtl\">\n    <div class=\"sl\">\n      <label>拟合方法<output id=\"outMethod\">最小曲率<\/output><\/label>\n      <input type=\"range\" id=\"inMethod\" min=\"0\" max=\"1\" step=\"1\" value=\"0\">\n    <\/div>\n  <\/div>\n  <svg id=\"trajChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"轨迹建模\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">井底井斜<\/span><b id=\"roIncEnd\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">最大全角变化率<\/span><b id=\"roDogleg\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"trajTip\">测点每 10—30m 一个，直接连点当轨迹误差大。最小曲率法把测段当成弧段累加，推算垂深、水平位移与全角变化率。全角变化率是轨迹平滑度与摩阻的关键指标，也是后面闭环安全守的边界。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 模型预测控制 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>模型预测控制（MPC）<\/b>：向前看几步 → 最优工具面角与滑动段<span class=\"qa-algo\">轨迹建模 · 模型预测控制<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 3—4<\/span>\n    <h2>模型预测控制：向前看几步给最优命令<\/h2>\n    <p class=\"leadline\">拖预测步数与目标井斜，看预测轨迹偏差怎么收敛、控制命令怎么变化。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"mpcCtl\">\n    <div class=\"sl\">\n      <label>预测步数<output id=\"outHorizon\">4<\/output><\/label>\n      <input type=\"range\" id=\"inHorizon\" min=\"2\" max=\"8\" step=\"1\" value=\"4\">\n    <\/div>\n    <div class=\"sl\">\n      <label>目标井斜<output id=\"outTarget\">50<\/output><\/label>\n      <input type=\"range\" id=\"inTarget\" min=\"35\" max=\"60\" step=\"1\" value=\"50\">\n    <\/div>\n  <\/div>\n  <svg id=\"mpcChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"模型预测控制\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">当前命令<\/span><b id=\"roCmd\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">目标井斜<\/span><b id=\"roTarget\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"mpcTip\">MPC 不只看当前偏差，而是用响应模型向前看几步，预测轨迹走向，给全局最优的造斜率命令。只盯当前偏差、命令频繁跳变，轨迹会来回摆。预测步数越大越稳，但响应模型不准时预测越不可靠。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 闭环安全 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">每步校验安全边界 → <b>闭环安全控制<\/b>（从「建议」到「控制」）<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 5—6<\/span>\n    <h2>闭环安全：把「建议」推进到安全控制<\/h2>\n    <p class=\"leadline\">拖安全阈值与「建议层/闭环」模式，看全角变化率是否越界、落靶率差多少。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"safeCtl\">\n    <div class=\"sl\">\n      <label>安全阈值<output id=\"outDog\">4.0<\/output><\/label>\n      <input type=\"range\" id=\"inDog\" min=\"2\" max=\"8\" step=\"0.5\" value=\"4\">\n    <\/div>\n    <div class=\"sl\">\n      <label>控制模式<output id=\"outMode\">闭环控制<\/output><\/label>\n      <input type=\"range\" id=\"inMode\" min=\"0\" max=\"1\" step=\"1\" value=\"1\">\n    <\/div>\n  <\/div>\n  <svg id=\"safeChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"闭环安全控制\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">安全状态<\/span><b id=\"roSafe\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">控制效果<\/span><b id=\"roAdvice\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"safeTip\">多数工具只停在「建议」层——给工程师建议、不校验安全边界。闭环控制每步校验全角变化率与摩阻，越界就降级/提醒人工，把建议推进到安全控制。安全要求极高，控制命令一旦出错可能冲出靶区。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 2<\/b><br>轨迹建模算井底位置。<\/div>\n    <div><b>实验 2 → STEP 4<\/b><br>MPC 向前看给最优命令。<\/div>\n    <div><b>实验 3 → STEP 5<\/b><br>闭环安全守边界。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：随钻轨迹由「设计造斜 + 测点噪声」合成，靶区已知、仅供对比；轨迹拟合、模型预测控制与闭环安全校验均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：随钻测点怎么一步步变成闭环轨迹控制',\n    stages: [\n      { name: '数据接入', tag: '随钻测点', dur: 4000, draw: function (t, g) { return F.stage1(t); } },\n      { name: '轨迹拟合', tag: '连续轨迹', dur: 4200, draw: function (t, g) { return F.stage2(t); } },\n      { name: '系统辨识', tag: '命令→造斜', dur: 4400, draw: function (t, g) { return F.stage3(t); } },\n      { name: '模型预测控制', tag: '向前看几步', dur: 4800, draw: function (t, g) { return F.stage4(t); } },\n      { name: '闭环安全', tag: '守边界', dur: 4600, draw: function (t, g) { return F.stage5(t); } },\n      { name: '落靶验收', tag: '落靶回流', dur: 4200, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的随钻轨迹数据演示轨迹建模、模型预测控制与闭环安全校验。","height":600};
  var META = {"id":"d3-trajectory-ctl","sceneId":"d3","title":"井眼轨迹智能控制：从「建议」到「闭环安全控制」"};
  var handle = null;
  var DEF = {"id":"d3-trajectory-ctl","sceneId":"d3","title":"井眼轨迹智能控制：从「建议」到「闭环安全控制」","methods":["opt"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"随钻测点+工具记录","desc":"每 10—30m 一测点"},{"label":"标注成本","value":"低","desc":"轨迹/工具记录无需标注"},{"label":"可见收益","value":"轨迹落靶+效率","desc":"少纠偏、降摩阻"},{"label":"难度","value":"高","desc":"闭环安全要求极高"}],"lede":"定向钻井要求实钻轨迹落在靶区窗口内，传统靠工程师根据随钻测量手动调整工具面与滑动段长度。调整依赖个人经验、轨迹波动大，滑动钻进效率低、频繁纠偏增加摩阻与卡钻风险。智能方法用模型预测控制给出工具面角与滑动段建议，并把「建议」推进到闭环安全控制。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>定向钻井要求实钻轨迹落在<b>靶区窗口<\/b>内。传统靠<b>钻井工程师<\/b>根据随钻测量（每 10—30m 一个测点）手动判断，调整<b>工具面角<\/b>与<b>滑动段长度<\/b>。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>靠个人经验<\/b>——同样的偏差，不同工程师给的命令差别大，轨迹波动大<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>滑动效率低<\/b>——滑动钻进机械钻速低，频繁纠偏增加摩阻与卡钻风险<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>只到「建议」层<\/b>——多数工具只给建议，工程师还要人工判断执行，闭环弱<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"手动调整轨迹的问题\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">手动纠偏：靠经验 · 波动大 · 只到建议层<\/text><rect x=\"20\" y=\"36\" width=\"280\" height=\"176\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"160\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">手动调整<\/text><rect x=\"36\" y=\"70\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"96\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#2b4a72\">看随钻测量<\/text><rect x=\"180\" y=\"70\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"230\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">凭经验纠偏<\/text><rect x=\"36\" y=\"112\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"96\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">命令差别大<\/text><rect x=\"180\" y=\"112\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"230\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">轨迹波动大<\/text><text x=\"160\" y=\"180\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#b26a39\" font-weight=\"700\">频繁纠偏 · 摩阻卡钻风险<\/text><text x=\"160\" y=\"198\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">滑动钻进效率低<\/text><rect x=\"316\" y=\"36\" width=\"284\" height=\"176\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"458\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">为什么难<\/text><text x=\"332\" y=\"82\" font-size=\"9.5\" fill=\"#4d565b\">· 井下响应模型难精确辨识<\/text><text x=\"332\" y=\"104\" font-size=\"9.5\" fill=\"#4d565b\">· 地层倾角/岩性是扰动<\/text><text x=\"332\" y=\"126\" font-size=\"9.5\" fill=\"#4d565b\">· 控制闭环安全要求极高<\/text><rect x=\"332\" y=\"150\" width=\"252\" height=\"46\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"344\" y=\"170\" font-size=\"8.5\" fill=\"#79828a\">工具面角 + 滑动段长度<\/text><text x=\"344\" y=\"186\" font-size=\"8.5\" fill=\"#b26a39\" font-weight=\"700\">多数工具只停在建议层<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>用<b>模型预测控制（MPC）<\/b>结合学习到的地层响应模型，向前看几步预测轨迹，给出<b>工具面角<\/b>与<b>滑动段长度<\/b>建议；再把「建议」推进到<b>闭环安全控制<\/b>——实时对比预测与实测，校验安全边界（全角变化率/狗腿度），偏离就自动修正。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>轨迹建模<\/b>——把随钻测点拟合成连续轨迹，推算井底位置与全角变化率<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>模型预测控制<\/b>——向前看几步，给出最优工具面角与滑动段，替代经验<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>闭环安全<\/b>——每步校验安全边界，把「建议」变成可执行的安全控制<\/span><\/div><\/div><p>落地形态：轨迹稳定落在靶区、少纠偏、摩阻低，且每一步都在安全边界内。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"智能轨迹控制流程\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">轨迹建模 + 模型预测控制 + 闭环安全<\/text><rect x=\"20\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"80\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">随钻测点<\/text><path d=\"M36 78 C60 62 90 76 116 68\" fill=\"none\" stroke=\"#7a8a9a\" stroke-width=\"2.6\"/><text x=\"80\" y=\"130\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">井斜/方位/井深<\/text><path d=\"M144 100 L168 100\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"172\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"237\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">轨迹建模<\/text><text x=\"237\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">拟合+位置推算<\/text><text x=\"237\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">全角变化率<\/text><path d=\"M306 100 L330 100\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"334\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"399\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">模型预测控制<\/text><text x=\"399\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">向前看几步<\/text><text x=\"399\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">工具面+滑动段<\/text><path d=\"M468 100 L492 100\" stroke=\"#2b4a72\" stroke-width=\"1.6\"/><rect x=\"496\" y=\"40\" width=\"104\" height=\"120\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"548\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">闭环安全<\/text><text x=\"548\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">每步校验<\/text><text x=\"548\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">安全边界<\/text><text x=\"310\" y=\"210\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">落靶稳定 · 少纠偏 · 摩阻低 · 每步在安全边界内<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>随钻测量轨迹<\/b>：井深、井斜、方位，每 10—30m 一个测点；<b>工具面与滑动记录<\/b>：按立柱记录，作为控制输入；<b>地层倾角与岩性<\/b>：邻井与随钻伽马，作为扰动因素。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"轨迹控制数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">轨迹控制需要的数据<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">随钻测量轨迹<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">井深/井斜/方位<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">每 10—30m 一测点<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#b26a39\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">工具面与滑动记录<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">工具面角/滑动段长度<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">按立柱记录<\/text><rect x=\"20\" y=\"106\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">地层倾角与岩性<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">邻井 + 随钻伽马<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">扰动因素<\/text><rect x=\"318\" y=\"106\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"330\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">靶区与设计轨迹<\/text><text x=\"330\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">靶点窗口/设计造斜率<\/text><text x=\"330\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">控制目标<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"32\" y=\"202\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">训练策略：轨迹建模 + 系统辨识 + 模型预测控制 + 闭环安全校验<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>井下响应难辨识<\/b>——工具面角与实际造斜的关系受地层/岩性影响，模型不准<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>闭环安全要求极高<\/b>——控制命令一旦出错可能冲出靶区甚至井喷，必须每步校验<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>测点稀疏<\/b>——10—30m 才一个测点，井底位置是推算的，有不确定性<\/span><\/div><\/div><p>改进路线按成本从低到高：先用<b>轨迹拟合<\/b>把测点连成连续轨迹、推算井底位置；再加<b>模型预测控制<\/b>向前看几步给最优命令；最后加<b>安全边界校验<\/b>把建议推进到闭环控制，并保留人工复核。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"轨迹控制难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 井下响应难辨识<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">地层/岩性扰动<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">系统辨识学响应<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">校正工具-造斜关系<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 闭环安全要求高<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">出错冲出靶区<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">模型预测控制<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">向前看+安全边界<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 测点稀疏<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">井底位置是推算的<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">轨迹拟合+不确定性<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">推算井底位置<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">轨迹拟合 → 系统辨识 → 模型预测控制 → 闭环安全校验<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一口定向井的轨迹控制改造","lead":["某定向井此前靠工程师凭经验手动调整工具面与滑动段，轨迹波动大、频繁纠偏、摩阻高。目标：用轨迹建模 + 模型预测控制给出最优命令，并推进到闭环安全控制。","注意第 3、4、5 步：系统辨识、模型预测控制、闭环安全是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["井","某定向井"],["测点","每 10—30m 一个"],["控制对象","工具面角+滑动段"],["现状","工程师手动"],["目标","MPC+闭环安全"],["安全要求","极高"]],"steps":[{"name":"测点数据接入","role":"数据","do":"读入随钻测量（井深/井斜/方位，每 10—30m 一测点）+ 工具面与滑动记录。示范页屏 1 顶部可看测点。","effect":"一份按井深排列的随钻测点序列，作为轨迹建模输入。","trap":"测点稀疏（10—30m 一个），直接连点当轨迹，井底位置推算误差大。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">数据接入：随钻测点 → 工具记录<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">随钻测量<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">井深/井斜/方位<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"170\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"291\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">工具面/滑动记录<\/text><text x=\"291\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">按立柱记录<\/text><path d=\"M380 72 L404 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"186\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"501\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">靶区设计<\/text><text x=\"501\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">控制目标<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：测点稀疏直接连点当轨迹 → 井底位置推算误差大<\/text><\/svg>"},{"name":"轨迹拟合","role":"数据","do":"把稀疏测点拟合成连续轨迹，推算井底位置与全角变化率。示范页屏 1 展示拟合轨迹。","effect":"一条连续轨迹 + 井底位置估计，供控制使用。","trap":"拟合过拟合测点噪声，轨迹抖动，控制命令跟着乱。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">轨迹拟合：测点 → 连续轨迹<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">稀疏测点<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">10—30m 一个<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"170\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"291\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">轨迹拟合<\/text><text x=\"291\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">最小曲率/样条<\/text><path d=\"M380 72 L404 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"186\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"501\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">连续轨迹+位置<\/text><text x=\"501\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">全角变化率<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：拟合过拟合测点噪声 → 轨迹抖动 → 控制命令跟着乱<\/text><\/svg>"},{"name":"系统辨识","role":"算法核心","do":"从历史工具面/滑动记录与实测轨迹，学出「命令 → 实际造斜」的响应模型，校正地层/岩性影响。示范页屏 2 展示辨识的响应曲线。","effect":"一个可预测的命令-响应模型，供模型预测控制使用。","trap":"地层突然变化（钻遇新岩性），旧辨识模型失效，控制命令失准。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">系统辨识：命令 → 实际造斜响应<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">工具面/滑动记录<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">控制输入<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">学响应模型<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">校正地层影响<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">命令-响应模型<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">供 MPC 用<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：地层突变钻遇新岩性 → 旧模型失效 → 控制命令失准<\/text><\/svg>"},{"name":"模型预测控制","role":"算法核心","do":"用响应模型向前看几步，预测轨迹走向，给出最优工具面角与滑动段长度，替代工程师经验。示范页屏 2 展示 MPC 命令与预测轨迹。","effect":"一段段最优控制命令，轨迹稳定朝向靶区。","trap":"只盯当前偏差、不看前方，命令频繁跳变，轨迹来回摆。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">MPC：向前看几步 → 最优命令<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">当前轨迹偏差<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">实测位置<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"170\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"291\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">向前看几步<\/text><text x=\"291\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">预测轨迹<\/text><path d=\"M380 72 L404 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"186\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"501\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">最优命令<\/text><text x=\"501\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">工具面+滑动段<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只盯当前偏差不看前方 → 命令频繁跳变 → 轨迹来回摆<\/text><\/svg>"},{"name":"闭环安全校验","role":"算法核心","do":"每步控制前校验安全边界（全角变化率/狗腿度、摩阻上限），超出就降级或提醒人工。示范页屏 3 展示安全边界校验。","effect":"控制命令始终在安全边界内，把「建议」推进到闭环安全控制。","trap":"只做建议、不校验，命令越过安全边界，摩阻/卡钻风险暴露。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">闭环安全：每步校验安全边界<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">控制命令<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">工具面+滑动段<\/text><path d=\"M188 72 L210 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">安全边界<\/text><text x=\"294\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">全角变化率/摩阻<\/text><path d=\"M378 72 L400 72\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">降级/人工复核<\/text><text x=\"499\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">闭环安全控制<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只做建议不校验 → 命令越过安全边界 → 摩阻卡钻风险<\/text><\/svg>"},{"name":"落靶验收与回流","role":"人工确认","do":"实钻轨迹与设计轨迹对比验收落靶，偏差反馈回辨识模型。示范页屏 3 展示落靶清单。","effect":"落靶率提升、少纠偏、摩阻低，且模型越用越准。","trap":"验收只看终点是否落靶，不看中间轨迹质量，摩阻问题被掩盖。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">验收：实钻 vs 设计 → 落靶 → 回流<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">实钻轨迹<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">落靶对比<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">轨迹质量<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">全角变化率/摩阻<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">反馈辨识<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">模型越用越准<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只看终点落靶不看中间轨迹质量 → 摩阻问题被掩盖<\/text><\/svg>"}],"metrics":{"title":"怎么算「控制对了」","html":"<p>轨迹控制用 <b>落靶率<\/b>（轨迹是否落在靶区窗口）与 <b>全角变化率/狗腿度<\/b>（轨迹平滑度）双重验收；<b>摩阻<\/b>与 <b>纠偏次数<\/b>衡量效率与风险。<\/p><p>最终还要看 <b>闭环安全性<\/b>：控制命令是否全程在安全边界内、异常时是否降级/提醒。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='轨迹控制效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>轨迹控制验收：落靶率 × 轨迹质量 × 闭环安全<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>控制效果<\/text><rect x='40' y='66' width='80' height='52' fill='#d9b78e'/><text x='80' y='96' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>落靶 72%<\/text><text x='80' y='112' text-anchor='middle' font-size='8' fill='#8a6b52'>手动纠偏<\/text><rect x='180' y='66' width='80' height='52' fill='#2f7d6b'/><text x='220' y='96' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>落靶 95%<\/text><text x='220' y='112' text-anchor='middle' font-size='8' fill='#b9d8cb'>MPC 闭环<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>落靶 ↑ 纠偏 ↓<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>轨迹质量 + 闭环<\/text><rect x='340' y='66' width='120' height='52' fill='#e7eef9' stroke='#41699b'/><text x='400' y='92' text-anchor='middle' font-size='9' fill='#2b4a72' font-weight='700'>全角变化率↓<\/text><text x='400' y='108' text-anchor='middle' font-size='8' fill='#79828a'>轨迹平滑<\/text><rect x='470' y='66' width='120' height='52' fill='#e6f1ec' stroke='#2f7d6b'/><text x='530' y='92' text-anchor='middle' font-size='9' fill='#22604f' font-weight='700'>全程安全边界<\/text><text x='530' y='108' text-anchor='middle' font-size='8' fill='#79828a'>闭环控制<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>安全要求极高 · 异常降级<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 落靶率 × 轨迹质量 × 闭环安全<\/text><\/svg><\/p>"},"fails":[{"name":"井下响应难辨识","why":"工具面角与实际造斜的关系受地层/岩性影响，模型不准，控制命令跟着失准。"},{"name":"闭环安全要求极高","why":"控制命令一旦出错可能冲出靶区，必须每步校验安全边界、异常降级。"},{"name":"测点稀疏","why":"10—30m 才一个测点，井底位置是推算的，有不确定性。"},{"name":"只停建议层","why":"多数工具只给建议，工程师还要人工判断执行，闭环弱，安全边界无人校验。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的随钻轨迹数据演示轨迹建模、模型预测控制与闭环安全校验。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
